DECLARE
  v_nb NUMBER := 0;
BEGIN
  FOR p IN (SELECT nom, stock FROM produits WHERE stock < 30) LOOP
    DBMS_OUTPUT.PUT_LINE('A réapprovisionner : ' || p.nom || ' (' || p.stock || ')');
    v_nb := v_nb + 1;
  END LOOP;
  DBMS_OUTPUT.PUT_LINE(v_nb || ' produit(s) à réapprovisionner');
END;
/

DECLARE
  v_prix produits.prix%TYPE;
BEGIN
  SELECT prix INTO v_prix FROM produits WHERE id = 1;
  IF v_prix <= 0 THEN
    RAISE_APPLICATION_ERROR(-20001, 'Prix invalide');
  END IF;
  DBMS_OUTPUT.PUT_LINE('Prix contrôlé : ' || v_prix);
END;
/
